  <script>
    const raw = `Date,Crude_Oil_Price
${(() => {
      return '';
    })()}`;
  </script>
  <script>
    const csvData = `__CSV_PLACEHOLDER__`;

    function parseCSV(csv) {
      const lines = csv.trim().split(/\r?\n/);
      const headers = lines[0].split(',');
      return lines.slice(1).map(line => {
        const [Date, Crude_Oil_Price] = line.split(',');
        return { Date: new Date(Date), price: parseFloat(Crude_Oil_Price) };
      }).filter(d => !Number.isNaN(d.price));
    }

    const data = parseCSV(csvData).sort((a,b)=>a.Date-b.Date);
    const prices = data.map(d=>d.price);
    const dates = data.map(d=>d.Date);

    const minPrice = Math.min(...prices), maxPrice = Math.max(...prices);
    const minIdx = prices.indexOf(minPrice), maxIdx = prices.indexOf(maxPrice);
    const range = maxPrice - minPrice;

    const start = data[0], end = data[data.length-1];
    const years = (end.Date - start.Date) / (365.2425*24*3600*1000);
    const cagr = Math.pow(end.price/start.price, 1/years)-1;

    function mean(arr){ return arr.reduce((a,b)=>a+b,0)/arr.length; }
    function std(arr){
      const m = mean(arr);
      return Math.sqrt(arr.reduce((s,x)=>s+Math.pow(x-m,2),0)/(arr.length-1));
    }
    function median(arr){
      const s=[...arr].sort((a,b)=>a-b);
      const n=s.length;
      return n%2?s[(n-1)/2]:(s[n/2-1]+s[n/2])/2;
    }
    function quantile(arr, q){
      const s=[...arr].sort((a,b)=>a-b);
      const pos=(s.length-1)*q, base=Math.floor(pos), rest=pos-base;
      return s[base+1]!==undefined?s[base]+rest*(s[base+1]-s[base]):s[base];
    }
    function fmt(v, n=2){ return Number(v).toLocaleString(undefined,{minimumFractionDigits:n,maximumFractionDigits:n}); }
    function ym(d){ return d.toISOString().slice(0,7); }

    const mom = data.map((d,i)=> i? d.price-data[i-1].price : null);
    const momPct = data.map((d,i)=> i? (d.price/data[i-1].price-1)*100 : null);
    const yoy = data.map((d,i)=> i>=12? d.price-data[i-12].price : null);
    const yoyPct = data.map((d,i)=> i>=12? (d.price/data[i-12].price-1)*100 : null);

    const maxMomAbsIdx = mom.map((v,i)=>({i,v:Math.abs(v??-Infinity)})).filter(x=>Number.isFinite(x.v)).sort((a,b)=>b.v-a.v)[0].i;
    const maxMomPctIdx = momPct.map((v,i)=>({i,v:Math.abs(v??-Infinity)})).filter(x=>Number.isFinite(x.v)).sort((a,b)=>b.v-a.v)[0].i;
    const maxYoyAbsIdx = yoy.map((v,i)=>({i,v:Math.abs(v??-Infinity)})).filter(x=>Number.isFinite(x.v)).sort((a,b)=>b.v-a.v)[0].i;
    const maxYoyPctIdx = yoyPct.map((v,i)=>({i,v:Math.abs(v??-Infinity)})).filter(x=>Number.isFinite(x.v)).sort((a,b)=>b.v-a.v)[0].i;

    const overallStd = std(prices);

    const decadeMap = new Map();
    data.forEach((d,i)=>{
      const decade = Math.floor(d.Date.getUTCFullYear()/10)*10;
      if(!decadeMap.has(decade)) decadeMap.set(decade, []);
      decadeMap.get(decade).push({date:d.Date, price:d.price, i});
    });
    const decadeStats = [...decadeMap.entries()].sort((a,b)=>a[0]-b[0]).map(([decade, arr])=>{
      const p = arr.map(x=>x.price);
      return {
        decade,
        months: p.length,
        avg: mean(p),
        med: median(p),
        sd: std(p),
        min: Math.min(...p),
        max: Math.max(...p),
        cv: std(p)/mean(p)
      };
    });
    const bestDecade = decadeStats.reduce((a,b)=> b.avg>a.avg?b:a, decadeStats[0]);

    document.getElementById('kpiRange').textContent = '$' + fmt(range);
    document.getElementById('kpiRangeSub').textContent = `${ym(dates[minIdx])} ($${fmt(minPrice)}) to ${ym(dates[maxIdx])} ($${fmt(maxPrice)})`;

    document.getElementById('kpiCagr').textContent = fmt(cagr*100,2) + '%';
    document.getElementById('kpiCagrSub').textContent = `${ym(start.Date)} ($${fmt(start.price)}) to ${ym(end.Date)} ($${fmt(end.price)})`;

    document.getElementById('kpiMom').textContent = '$' + fmt(mom[maxMomAbsIdx]) + ' (' + fmt(momPct[maxMomAbsIdx],2) + '%)';
    document.getElementById('kpiMomSub').textContent = `Occurred in ${ym(data[maxMomAbsIdx].Date)}; max % move in ${ym(data[maxMomPctIdx].Date)} (${fmt(momPct[maxMomPctIdx],2)}%)`;

    document.getElementById('kpiDecade').textContent = `${bestDecade.decade}s`;
    document.getElementById('kpiDecadeSub').textContent = `Mean monthly price: $${fmt(bestDecade.avg)}`;

    document.getElementById('kpiStd').textContent = '$' + fmt(overallStd);
    document.getElementById('kpiStdSub').textContent = 'Sample standard deviation across all monthly observations';

    const execInsights = [
      `The monthly crude oil price rises from $${fmt(start.price)} (${ym(start.Date)}) to $${fmt(end.price)} (${ym(end.Date)}), equivalent to a ${fmt(((end.price/start.price)-1)*100,1)}% cumulative increase over ${fmt(years,2)} years.`,
      `The all-sample mean is $${fmt(mean(prices))}, median is $${fmt(median(prices))}, and standard deviation is $${fmt(overallStd)}; mean > median indicates right-skew driven by high-price regimes.`,
      `The highest monthly observation is $${fmt(maxPrice)} in ${ym(dates[maxIdx])}, while the lowest is $${fmt(minPrice)} in ${ym(dates[minIdx])}.`,
      `The decade with the highest mean monthly price is the ${bestDecade.decade}s ($${fmt(bestDecade.avg)}), indicating structural elevation versus prior decades.`
    ];
    document.getElementById('execInsights').innerHTML = execInsights.map(t=>`<li>${t}</li>`).join('');

    const decadeTable = document.getElementById('decadeTable');
    decadeTable.innerHTML = `
      <thead><tr>
        <th>Decade</th><th>Months</th><th>Mean</th><th>Median</th><th>Std Dev</th><th>Min</th><th>Max</th><th>CV</th>
      </tr></thead>
      <tbody>
        ${decadeStats.map(d=>`<tr><td>${d.decade}s</td><td>${d.months}</td><td>$${fmt(d.avg)}</td><td>$${fmt(d.med)}</td><td>$${fmt(d.sd)}</td><td>$${fmt(d.min)}</td><td>$${fmt(d.max)}</td><td>${fmt(d.cv*100,1)}%</td></tr>`).join('')}
      </tbody>`;

    const summaryStats = [
      ['Observations', data.length],
      ['Start date', ym(start.Date)],
      ['End date', ym(end.Date)],
      ['Mean', '$'+fmt(mean(prices))],
      ['Median', '$'+fmt(median(prices))],
      ['Standard deviation', '$'+fmt(overallStd)],
      ['Min', '$'+fmt(minPrice)],
      ['10th percentile', '$'+fmt(quantile(prices,0.10))],
      ['25th percentile', '$'+fmt(quantile(prices,0.25))],
      ['75th percentile', '$'+fmt(quantile(prices,0.75))],
      ['90th percentile', '$'+fmt(quantile(prices,0.90))],
      ['Max', '$'+fmt(maxPrice)]
    ];
    document.getElementById('summaryTable').innerHTML = `
      <thead><tr><th>Metric</th><th>Value</th></tr></thead>
      <tbody>${summaryStats.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td></tr>`).join('')}</tbody>`;

    const shockList = [
      `Largest absolute MoM change: $${fmt(mom[maxMomAbsIdx])} (${fmt(momPct[maxMomAbsIdx],2)}%) in ${ym(data[maxMomAbsIdx].Date)}.`,
      `Largest percentage MoM change: ${fmt(momPct[maxMomPctIdx],2)}% (absolute $${fmt(mom[maxMomPctIdx])}) in ${ym(data[maxMomPctIdx].Date)}.`,
      `Largest absolute YoY change: $${fmt(yoy[maxYoyAbsIdx])} (${fmt(yoyPct[maxYoyAbsIdx],2)}%) in ${ym(data[maxYoyAbsIdx].Date)}.`,
      `Largest percentage YoY change: ${fmt(yoyPct[maxYoyPctIdx],2)}% (absolute $${fmt(yoy[maxYoyPctIdx])}) in ${ym(data[maxYoyPctIdx].Date)}.`
    ];
    document.getElementById('shockList').innerHTML = shockList.map(s=>`<li>${s}</li>`).join('');

    const conclusionList = [
      `The long-run series shows a structural transition from low/stable nominal prices in the early decades to higher and more volatile regimes post-2000.`,
      `Volatility is episodic rather than constant; shock windows create concentrated drawdowns and rebounds visible in both MoM and YoY deltas.`,
      `The 2010s register the highest decade-average level ($${fmt(bestDecade.avg)}), while the 2020s continue to exhibit large dispersion and event sensitivity.`,
      `As this dataset includes observations through ${ym(end.Date)}, analysts should separately validate whether latest points are observed or projected before forecasting extensions.`
    ];
    document.getElementById('conclusionList').innerHTML = conclusionList.map(s=>`<li>${s}</li>`).join('');

    const annotationPoints = [
      {x: dates[maxIdx], y: maxPrice, label: `Peak ${ym(dates[maxIdx])}: $${fmt(maxPrice)}`},
      {x: dates[minIdx], y: minPrice, label: `Trough ${ym(dates[minIdx])}: $${fmt(minPrice)}`},
      {x: data[maxMomAbsIdx].Date, y: data[maxMomAbsIdx].price, label: `Max MoM abs ${ym(data[maxMomAbsIdx].Date)}`},
      {x: data[maxYoyAbsIdx].Date, y: data[maxYoyAbsIdx].price, label: `Max YoY abs ${ym(data[maxYoyAbsIdx].Date)}`}
    ];

    new Chart(document.getElementById('lineChart'), {
      type: 'line',
      data: {
        datasets: [{
          label: 'Crude Oil Price (USD/bbl)',
          data: data.map(d=>({x:d.Date, y:d.price})),
          borderColor: '#1d4ed8',
          backgroundColor: 'rgba(29,78,216,0.08)',
          borderWidth: 2,
          fill: true,
          pointRadius: 0,
          tension: 0.15
        }, {
          type:'scatter',
          label:'Key points',
          data: annotationPoints,
          pointRadius: 4,
          pointBackgroundColor: '#b91c1c'
        }]
      },
      options: {
        maintainAspectRatio: false,
        interaction: {mode:'nearest', intersect:false},
        scales: {
          x: {type:'time', time:{unit:'year'}, grid:{color:'#eef2f7'}, ticks:{maxRotation:0}},
          y: {title:{display:true,text:'USD per barrel'}, grid:{color:'#eef2f7'}}
        },
        plugins: {
          legend: {display:true},
          tooltip: {callbacks:{label:(ctx)=> `${ctx.dataset.label}: $${fmt(ctx.parsed.y)}`}}
        }
      }
    });

    new Chart(document.getElementById('decadeAvgChart'), {
      type:'bar',
      data:{
        labels: decadeStats.map(d=>`${d.decade}s`),
        datasets:[{label:'Average price', data:decadeStats.map(d=>d.avg), backgroundColor:'#0f766e'}]
      },
      options:{
        maintainAspectRatio:false,
        scales:{y:{title:{display:true,text:'USD/bbl'},grid:{color:'#eef2f7'}},x:{grid:{display:false}}},
        plugins:{legend:{display:false}, tooltip:{callbacks:{label:(ctx)=>`$${fmt(ctx.parsed.y)}`}}}
      }
    });

    new Chart(document.getElementById('decadeVolChart'), {
      type:'bar',
      data:{
        labels: decadeStats.map(d=>`${d.decade}s`),
        datasets:[{label:'Standard deviation', data:decadeStats.map(d=>d.sd), backgroundColor:'#1d4ed8'}]
      },
      options:{
        maintainAspectRatio:false,
        scales:{y:{title:{display:true,text:'USD/bbl'},grid:{color:'#eef2f7'}},x:{grid:{display:false}}},
        plugins:{legend:{display:false}, tooltip:{callbacks:{label:(ctx)=>`$${fmt(ctx.parsed.y)}`}}}
      }
    });

    new Chart(document.getElementById('momChart'), {
      type:'bar',
      data:{
        labels:data.map(d=>d.Date),
        datasets:[{label:'MoM % change', data:momPct, backgroundColor: momPct.map(v=>v>=0?'rgba(15,118,110,.7)':'rgba(185,28,28,.7)')}]
      },
      options:{
        maintainAspectRatio:false,
        scales:{x:{type:'time',time:{unit:'year'},grid:{display:false}},y:{title:{display:true,text:'%'},grid:{color:'#eef2f7'}}},
        plugins:{legend:{display:false}, tooltip:{callbacks:{label:(ctx)=>`${fmt(ctx.parsed.y,2)}%`}}}
      }
    });

    new Chart(document.getElementById('yoyChart'), {
      type:'line',
      data:{
        datasets:[{label:'YoY % change', data:data.map((d,i)=>({x:d.Date,y:yoyPct[i]})), borderColor:'#7c3aed', pointRadius:0, borderWidth:1.8, tension:0.12}]
      },
      options:{
        maintainAspectRatio:false,
        scales:{x:{type:'time',time:{unit:'year'},grid:{display:false}},y:{title:{display:true,text:'%'},grid:{color:'#eef2f7'}}},
        plugins:{legend:{display:false}, tooltip:{callbacks:{label:(ctx)=>`${fmt(ctx.parsed.y,2)}%`}}}
      }
    });

    // Histogram
    const bins = 24;
    const lo = minPrice, hi = maxPrice, bw = (hi-lo)/bins;
    const counts = Array(bins).fill(0);
    prices.forEach(p=>{
      let idx = Math.floor((p-lo)/bw);
      if(idx===bins) idx=bins-1;
      counts[idx]++;
    });
    const histLabels = counts.map((_,i)=>`$${fmt(lo+i*bw,0)}–$${fmt(lo+(i+1)*bw,0)}`);

    new Chart(document.getElementById('histChart'), {
      type:'bar',
      data:{labels:histLabels, datasets:[{label:'Count', data:counts, backgroundColor:'#334155'}]},
      options:{
        maintainAspectRatio:false,
        scales:{x:{ticks:{display:false},grid:{display:false}},y:{title:{display:true,text:'Months'},grid:{color:'#eef2f7'}}},
        plugins:{legend:{display:false}}
      }
    });
  </script>
</body>
</html>
